create table claims (name varchar(80) primary key);
create table role_claims (role_id bigint not null references roles(role_id), claim varchar(80) not null references claims(name), primary key(role_id,claim));
create table user_claims (user_id bigint not null references users(id), claim varchar(80) not null references claims(name), primary key(user_id,claim));
alter table users add column version bigint not null default 0;
create table audit_events (id bigint generated by default as identity primary key, actor_id bigint not null references users(id), action varchar(80) not null, resource varchar(80) not null, resource_id bigint, detail varchar(500) not null, occurred_at timestamptz not null default current_timestamp);
create index audit_resource_idx on audit_events(resource, resource_id, id);
insert into claims(name) values ('dashboard.read'),('client.read'),('client.write'),('client.export'),('iam.user.read'),('iam.user.manage'),('account.write'),('task.read'),('task.read.all'),('task.write'),('task.manage'),('leave.read'),('leave.read.all'),('leave.write'),('leave.review'),('staff-report.read'),('staff-report.read.all'),('staff-report.write'),('staff-report.review'),('finance.read'),('finance.write'),('finance.approve'),('finance.reverse'),('report.read'),('backup.manage');
insert into role_claims select r.role_id,c.name from roles r cross join claims c where lower(r.role_name)='admin';
insert into role_claims select r.role_id,c.name from roles r cross join claims c where lower(r.role_name) in ('user','users') and c.name in ('dashboard.read','client.read','account.write','task.read','task.write','leave.read','leave.write','staff-report.read','staff-report.write');

insert into claims(name) values ('expense.read'),('expense.write'),('expense.approve');
insert into role_claims select r.role_id,c.name from roles r cross join claims c where lower(r.role_name)='admin' and c.name like 'expense.%';
insert into role_claims select r.role_id,c.name from roles r cross join claims c where lower(r.role_name) in ('user','users') and c.name in ('expense.read','expense.write');
